mapper.select:
SELECT r.id, r.user_id, u.username, u.building, u.room_no, r.type, r.description, r.urgency, r.images, r.status, r.result, r.accept_time, r.finish_time, r.cancel_time, r.create_time, rc.star AS star, rc.content AS comment_content FROM repair_order r JOIN `user` u ON u.id = r.user_id LEFT JOIN repair_comment rc ON rc.order_id = r.id
AND r.status = #{status}
AND r.status != 5
AND r.type = #{type}
AND r.urgency = #{urgency}
ORDER BY r.urgency DESC, r.create_time DESC, r.id DESC
